// INV-DDL05-001/002/003: future PostgreSQL rehearsal only. Do not run in TASK-0032.
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import pg from 'pg';
import test from 'node:test';

const { Client } = pg;
const database = 'detran_r7_ctg1_a2';
const admin = 'aarusso';
const expectedUrl = `postgresql://${admin}@localhost/${database}`;
const urlVariable = 'DETRAN_DDL05_ADMIN_DATABASE_URL';
const root = resolve(dirname(fileURLToPath(import.meta.url)), '../../..');
const fields = [
  'family',
  'name',
  'description',
  'apps',
  'is_staff',
  'source',
  'introduced_on',
];
const sentinel = '2000-01-01 00:00:00.000000+00';
const projection = `key, family, name, description, apps, is_staff, source,
  introduced_on::text AS introduced_on,
  to_char(created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS.US') AS created_at,
  to_char(updated_at AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS.US') AS updated_at`;

function blocked(message) {
  return new Error(`BLOCKED (not behavioral RED): ${message}`);
}

function explicitUrl() {
  if (process.env.DETRAN_DDL05_DB_TEST_AUTHORIZED !== '1')
    throw blocked('dedicated DDL05 DB rehearsal needs explicit authorization');
  const raw = process.env[urlVariable];
  if (!raw) throw blocked(`${urlVariable} is required; no DB fallback`);
  if (raw !== expectedUrl)
    throw blocked(`${urlVariable} must exactly equal ${expectedUrl}`);
  return raw;
}

async function rows(client) {
  return (
    await client.query(
      `SELECT ${projection} FROM auth.role_catalog ORDER BY key`,
    )
  ).rows;
}

async function row(client, key) {
  const result = await client.query(
    `SELECT ${projection} FROM auth.role_catalog WHERE key = $1`,
    [key],
  );
  assert.equal(result.rowCount, 1, `catalogue row ${key} must exist`);
  return result.rows[0];
}

async function updateCount(client) {
  const result = await client.query(`
    SELECT n_tup_upd::bigint::text AS count
    FROM pg_stat_xact_user_tables
    WHERE relid = 'auth.role_catalog'::regclass
  `);
  assert.equal(result.rowCount, 1, 'transactional UPDATE counter required');
  return BigInt(result.rows[0].count);
}

async function preflight(client) {
  const result = await client.query(`
    SELECT current_database() AS database, current_user AS principal,
           r.rolsuper AS superuser, r.rolbypassrls AS bypass_rls,
           pg_has_role(current_user, c.relowner, 'MEMBER') AS owns_table,
           has_table_privilege(current_user, c.oid, 'INSERT, UPDATE, DELETE') AS can_mutate,
           (SELECT count(*)::integer FROM pg_stat_activity
            WHERE datname = current_database() AND backend_type = 'client backend') AS clients
    FROM pg_roles r, pg_class c
    WHERE r.rolname = current_user AND c.oid = 'auth.role_catalog'::regclass
  `);
  if (result.rowCount !== 1) throw blocked('admin/table identity unavailable');
  const identity = result.rows[0];
  if (identity.database !== database || identity.principal !== admin)
    throw blocked('current_database/current_user differs from dedicated admin');
  if (!identity.owns_table && !identity.superuser)
    throw blocked('admin lacks DDL ownership authority on auth.role_catalog');
  if (!identity.can_mutate)
    throw blocked('admin lacks INSERT/UPDATE/DELETE privilege');
  if (identity.clients !== 1)
    throw blocked('dedicated database has concurrent client sessions');
  const lock = await client.query(
    'SELECT pg_try_advisory_xact_lock(7007, 5) AS acquired',
  );
  if (lock.rows[0].acquired !== true)
    throw blocked('dedicated DDL05 transaction lock unavailable');
}

function sqlParts(ddl) {
  const inserts = [
    ...ddl.matchAll(
      /INSERT\s+INTO\s+auth\.role_catalog\s*\(\s*key\s*,\s*family\s*,\s*name\s*,\s*description\s*,\s*apps\s*,\s*is_staff\s*,\s*source\s*,\s*introduced_on\s*\)\s+VALUES\s*([\s\S]*?)\s+ON\s+CONFLICT\s*\(key\)\s+DO\s+UPDATE\s+SET\s*([\s\S]*?);/gi,
    ),
  ];
  assert.equal(inserts.length, 1, 'exactly one DDL05 upsert required');
  const match = inserts[0];
  return { statement: match[0], values: match[1] };
}

async function assertCanonicalBaseline(client, values) {
  const result = await client.query(`
    WITH canonical (key, family, name, description, apps, is_staff, source, introduced_on)
    AS (VALUES ${values})
    SELECT count(*)::integer AS expected,
      count(r.key)::integer AS present,
      count(*) FILTER (WHERE r.key IS NULL OR
        ROW(r.family, r.name, r.description, r.apps, r.is_staff, r.source, r.introduced_on)
        IS DISTINCT FROM
        ROW(c.family, c.name, c.description, c.apps, c.is_staff, c.source, c.introduced_on::date)
      )::integer AS divergent
    FROM canonical c LEFT JOIN auth.role_catalog r USING (key)
  `);
  const { expected, present, divergent } = result.rows[0];
  const actual = await client.query(
    'SELECT count(*)::integer AS count FROM auth.role_catalog',
  );
  if (
    expected !== 36 ||
    present !== 36 ||
    actual.rows[0].count !== 36 ||
    divergent !== 0
  )
    throw blocked('DDL05 catalogue is not the exact canonical 36-row baseline');
}

function canonicalValues(actual) {
  return Object.fromEntries(fields.map((field) => [field, actual[field]]));
}

async function assertUnchangedOthers(client, before, key) {
  const after = await rows(client);
  assert.deepEqual(
    after.filter((entry) => entry.key !== key),
    before.filter((entry) => entry.key !== key),
    'unaffected catalogue rows must preserve fields and timestamps',
  );
}

test('dado catálogo canônico quando aplica DDL05 em transação então igualdade, divergência, repetição e ausência respeitam idempotência', async () => {
  const url = explicitUrl();
  const ddl = await readFile(
    resolve(root, 'backend/database/ddl/05-role-catalog.sql'),
    'utf8',
  );
  const { statement, values } = sqlParts(ddl);
  const client = new Client({ connectionString: url });
  let connected = false;
  let begun = false;
  let initial;
  try {
    await client.connect();
    connected = true;
    const destination = await client.query(
      'SELECT current_database() AS database, current_user AS principal',
    );
    if (
      destination.rows[0].database !== database ||
      destination.rows[0].principal !== admin
    )
      throw blocked(
        'current_database/current_user differs from dedicated admin',
      );
    initial = await rows(client);
    await client.query('BEGIN');
    begun = true;
    await preflight(client);
    await assertCanonicalBaseline(client, values);

    const target = 'rait-analyst';
    const canonical = await row(client, target);
    const beforeEqual = await updateCount(client);
    await client.query(statement);
    assert.equal(
      await updateCount(client),
      beforeEqual,
      'equal apply must do zero row UPDATEs',
    );
    assert.deepEqual(
      await rows(client),
      initial,
      'equal apply changes no row or timestamp',
    );

    const variants = {
      family: 'teat',
      name: 'DDL05 divergent name',
      description: 'DDL05 divergent description',
      apps: ['rait', 'dashboard'],
      is_staff: false,
      source: 'DDL05 divergent source',
      introduced_on: '2025-01-01',
    };
    for (const field of [...fields, 'all']) {
      const overrides =
        field === 'all' ? variants : { [field]: variants[field] };
      const assignments = Object.keys(overrides)
        .map((column, index) => `${column} = $${index + 2}`)
        .join(', ');
      await client.query(
        `UPDATE auth.role_catalog SET ${assignments}, updated_at = $1::timestamptz WHERE key = $${Object.keys(overrides).length + 2}`,
        [sentinel, ...Object.values(overrides), target],
      );
      const divergent = await row(client, target);
      assert.notDeepEqual(
        canonicalValues(divergent),
        canonicalValues(canonical),
      );
      const beforeRepair = await updateCount(client);
      await client.query(statement);
      assert.equal(
        await updateCount(client),
        beforeRepair + 1n,
        `${field}: exactly one row UPDATE`,
      );
      const repaired = await row(client, target);
      assert.deepEqual(canonicalValues(repaired), canonicalValues(canonical));
      assert.equal(repaired.created_at, canonical.created_at);
      assert.notEqual(repaired.updated_at, divergent.updated_at);
      assert.ok(repaired.updated_at > '2000-01-01 00:00:00.000000');
      await assertUnchangedOthers(client, initial, target);
      const beforeReapply = await updateCount(client);
      await client.query(statement);
      assert.equal(
        await updateCount(client),
        beforeReapply,
        `${field}: reapply must not UPDATE`,
      );
      assert.deepEqual(
        await row(client, target),
        repaired,
        `${field}: reapply stable`,
      );
    }

    const references = await client.query(`
      SELECT n.nspname AS schema, c.relname AS relation, a.attname AS column
      FROM pg_constraint fk
      JOIN pg_class c ON c.oid = fk.conrelid
      JOIN pg_namespace n ON n.oid = c.relnamespace
      JOIN LATERAL unnest(fk.conkey) AS k(attnum) ON true
      JOIN pg_attribute a ON a.attrelid = c.oid AND a.attnum = k.attnum
      WHERE fk.contype = 'f' AND fk.confrelid = 'auth.role_catalog'::regclass
    `);
    if (
      references.rows.length !== 1 ||
      references.rows[0].schema !== 'auth' ||
      references.rows[0].relation !== 'roles' ||
      references.rows[0].column !== 'key'
    )
      throw blocked(
        'missing-row fixture requires a known single auth.roles FK',
      );
    const candidate = await client.query(`
      SELECT c.key FROM auth.role_catalog c
      WHERE NOT EXISTS (SELECT 1 FROM auth.roles r WHERE r.key = c.key)
      ORDER BY c.key LIMIT 1
    `);
    if (candidate.rowCount !== 1)
      throw blocked(
        'no canonical role key can be removed without violating FK',
      );
    const missingKey = candidate.rows[0].key;
    const beforeMissing = await rows(client);
    const missingCanonical = await row(client, missingKey);
    await client.query('DELETE FROM auth.role_catalog WHERE key = $1', [
      missingKey,
    ]);
    const beforeInsert = await updateCount(client);
    await client.query(statement);
    assert.equal(
      await updateCount(client),
      beforeInsert,
      'missing-row apply must INSERT, not UPDATE',
    );
    const inserted = await row(client, missingKey);
    assert.deepEqual(
      canonicalValues(inserted),
      canonicalValues(missingCanonical),
    );
    assert.ok(
      inserted.created_at && inserted.updated_at,
      'INSERT defaults required',
    );
    const beforeFinalReapply = await updateCount(client);
    await client.query(statement);
    assert.equal(await updateCount(client), beforeFinalReapply);
    assert.deepEqual(await row(client, missingKey), inserted);
    await assertUnchangedOthers(client, beforeMissing, missingKey);
  } finally {
    if (connected) {
      try {
        if (begun) await client.query('ROLLBACK');
        if (initial)
          assert.deepEqual(
            await rows(client),
            initial,
            'ROLLBACK restores initial catalogue',
          );
      } finally {
        await client.end();
      }
    }
  }
});

// INV-DDL05-001/002/003: independent, database-free sensor for the manual DDL05.
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import test from 'node:test';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '../../..');
const ddl = await readFile(
  resolve(root, 'backend/database/ddl/05-role-catalog.sql'),
  'utf8',
);
const fields = [
  'family',
  'name',
  'description',
  'apps',
  'is_staff',
  'source',
  'introduced_on',
];
const keys = [
  'ADMIN',
  'ADMIN_CLINICA',
  'MEDICO',
  'PSICOLOGO',
  'RECEPCAO',
  'TECNICO_BIOMETRIA',
  'AUDITOR',
  'GESTOR',
  'SUPERVISOR',
  'GESTOR_DETRAN',
  'JUNTA',
  'CETRAN',
  'DPO',
  'SUPORTE',
  'CANDIDATO',
  'field-agent',
  'field-supervisor',
  'processing-operator',
  'traffic-authority',
  'agency-admin',
  'technical-admin',
  'bi-analyst',
  'integration-operator',
  'rait-analyst',
  'rait-coordinator',
  'rait-secretary',
  'rait-signing-authority',
  'rait-central-authority',
  'rait-rapporteur',
  'rait-chair',
  'rait-manager',
  'rait-hr',
  'rait-finance',
  'dash-operator',
  'dash-duty-owner',
  'CIDADAO',
];

const inserts = [
  ...ddl.matchAll(
    /INSERT\s+INTO\s+auth\.role_catalog\s*\(\s*key\s*,\s*family\s*,\s*name\s*,\s*description\s*,\s*apps\s*,\s*is_staff\s*,\s*source\s*,\s*introduced_on\s*\)\s+VALUES\s*([\s\S]*?)\s+ON\s+CONFLICT\s*\(key\)\s+DO\s+UPDATE\s+SET\s*([\s\S]*?);/gi,
  ),
];

test('dado DDL05 quando localiza upsert então existe um conflito por key', () => {
  assert.equal(inserts.length, 1, 'one executable role-catalog upsert');
  assert.equal(
    [...ddl.matchAll(/^INSERT\s+INTO\s+auth\.role_catalog\b/gm)].length,
    1,
  );
  assert.equal([...ddl.matchAll(/\bON\s+CONFLICT\s*\(/gi)].length, 1);
});

test('dado catálogo canônico quando lê VALUES então preserva 36 chaves e valores literais', () => {
  assert.equal(inserts.length, 1);
  const values = inserts[0][1];
  const actualKeys = [
    ...values.matchAll(
      /^\s*\('([^']+)',\s*'(?:pec|teat|rait|dashboard|citizen)'/gm,
    ),
  ].map((match) => match[1]);
  assert.equal(actualKeys.length, 36);
  assert.deepEqual(actualKeys, keys);
  assert.equal(new Set(actualKeys).size, 36);
  assert.equal(
    createHash('sha256').update(values).digest('hex'),
    '4cc02a80c0cae4747c3cf3f51a8eb54c0d8943f267227856a6dc8fe91a62e9cd',
    'the complete literal VALUES block, including all eight attributes per row, must remain byte-identical',
  );
});

test('dado conflito quando atualiza então SET conserva exatamente sete EXCLUDED e clock', () => {
  assert.equal(inserts.length, 1);
  const body = inserts[0][2];
  const set = body.split(/\bWHERE\b/i)[0];
  const assignments = set
    .replace(/--[^\n]*/g, '')
    .split(',')
    .map((value) => value.trim().replace(/\s+/g, ' '));
  assert.deepEqual(assignments, [
    ...fields.map((field) => `${field} = EXCLUDED.${field}`),
    'updated_at = clock_timestamp()',
  ]);
  assert.doesNotMatch(set, /\bcreated_at\b/i);
});

test('dado linha igual quando avalia conflito então guarda ROW null-safe usa somente os sete pares posicionais', () => {
  assert.equal(inserts.length, 1);
  const body = inserts[0][2].replace(/--[^\n]*/g, '');
  const where = body.match(/\bWHERE\b([\s\S]*)$/i);
  assert.ok(
    where,
    'INV-DDL05-001: missing seven-field null-safe conflict guard',
  );
  const columnList = fields.join(',');
  const actual = where[1].replace(/\s+/g, '').toLowerCase();
  const expected = `row(${fields.map((field) => `role_catalog.${field}`).join(',')})isdistinctfromrow(${fields.map((field) => `excluded.${field}`).join(',')})`;
  assert.equal(actual, expected, `guard must compare exactly ${columnList}`);
  assert.doesNotMatch(where[1], /\b(?:created_at|updated_at)\b/i);
});

// CTG-0001-C4-OD V3, F1/F8: the real apply is exercised against an isolated
// copy of the closed DDL inventory. Never patch a production SQL or apply file.
import { spawn } from 'node:child_process';
import { createHash } from 'node:crypto';
import {
  chmod,
  copyFile,
  mkdtemp,
  mkdir,
  readFile,
  readdir,
  rm,
  writeFile,
} from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import pg from 'pg';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';

const { Client } = pg;
const repo = resolve(
  dirname(fileURLToPath(import.meta.url)),
  '../../../../../..',
);
const databaseDir = join(repo, 'backend/database');
const inventoryPath = join(
  repo,
  'work/rounds/R-0007/reports/CTG-0001-C4-OD-V3-DDL-INVENTORY.md',
);
const manual = [
  '19-rait-priority-pre.sql',
  '19-rait-priority-enforce.sql',
  '19-rait-priority-verify.sql',
] as const;
const expectedDatabase = 'detran_r7_ctg1_a2';
const legacyCaseId = '00000000-0000-7000-8000-000010000020';
const unknownLegacyPriority = 'legacy_unmapped_task0028';

type Snapshot = {
  schema: string;
  data: string;
  globals: string;
  roles: string;
};
type ApplyResult = { code: number | null; output: string };
type LegacyTable = {
  schema: string;
  table: string;
  columns: string[];
  hash: string;
};

function digest(value: string): string {
  return createHash('sha256').update(value).digest('hex');
}

function requiredUrl(name: string): URL {
  const raw = process.env[name];
  if (!raw)
    throw new Error(
      `${name} is required; missing DB context is BLOCKED, not RED`,
    );
  const url = new URL(raw);
  if (!['postgres:', 'postgresql:'].includes(url.protocol))
    throw new Error(`${name} must be a PostgreSQL URL`);
  if (decodeURIComponent(url.pathname.slice(1)) !== expectedDatabase)
    throw new Error(`${name} must target ${expectedDatabase}`);
  return url;
}

function connectionEnvironment(url: URL): NodeJS.ProcessEnv {
  return {
    ...process.env,
    DB_NAME: expectedDatabase,
    DB_HOST: url.hostname,
    DB_PORT: url.port || '5432',
    DB_USER: decodeURIComponent(url.username),
    DB_PASSWORD: decodeURIComponent(url.password),
    PGHOST: url.hostname,
    PGPORT: url.port || '5432',
    PGUSER: decodeURIComponent(url.username),
    PGPASSWORD: decodeURIComponent(url.password),
    PGDATABASE: expectedDatabase,
  };
}

async function run(
  command: string,
  args: string[],
  options: { cwd: string; env: NodeJS.ProcessEnv; timeout?: number },
): Promise<ApplyResult> {
  return new Promise((resolvePromise, reject) => {
    const child = spawn(command, args, {
      cwd: options.cwd,
      env: options.env,
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    let output = '';
    const timer = setTimeout(
      () => child.kill('SIGKILL'),
      options.timeout ?? 120_000,
    );
    child.stdout.on('data', (chunk: Buffer) => (output += chunk.toString()));
    child.stderr.on('data', (chunk: Buffer) => (output += chunk.toString()));
    child.on('error', reject);
    child.on('close', (code) => {
      clearTimeout(timer);
      resolvePromise({ code, output });
    });
  });
}

async function inventory(): Promise<string[]> {
  const lines = (await readFile(inventoryPath, 'utf8'))
    .split('\n')
    .filter((line) => line.startsWith('- `backend/database/ddl/'));
  const files = lines.map((line) => line.match(/ddl\/([^`]+)`/)?.[1]);
  if (files.length !== 49 || files.some((file) => !file))
    throw new Error('The closed 49-DDL inventory is incomplete');
  return files as string[];
}

async function isolatedCopy(syntheticManual = false): Promise<string> {
  const directory = await mkdtemp(join(tmpdir(), 'rait-priority-upgrade-'));
  await mkdir(join(directory, 'ddl'));
  await copyFile(join(databaseDir, 'apply.sh'), join(directory, 'apply.sh'));
  const listed = await inventory();
  const present = (await readdir(join(databaseDir, 'ddl')))
    .filter((name) => name.endsWith('.sql'))
    .sort();
  const presentManual = manual.filter((name) => present.includes(name));
  if (presentManual.length !== 0 && presentManual.length !== manual.length)
    throw new Error(
      'Partial TASK-0029 SQL candidate is not an inventory state',
    );
  if (!syntheticManual && presentManual.length !== manual.length)
    throw new Error('TASK-0029 SQL candidate is required for DB rehearsal');
  expect(present).toEqual(
    presentManual.length === manual.length
      ? [...listed, ...manual].sort()
      : [...listed].sort(),
  );
  for (const name of present)
    await copyFile(
      join(databaseDir, 'ddl', name),
      join(directory, 'ddl', name),
    );
  if (syntheticManual && presentManual.length === 0)
    for (const name of manual)
      await writeFile(
        join(directory, 'ddl', name),
        '-- synthetic static probe only\n',
      );
  return directory;
}

async function inject(
  directory: string,
  after: string,
  sql: string,
): Promise<void> {
  const path = join(directory, 'ddl', after);
  const original = await readFile(path, 'utf8');
  await writeFile(path, `${original}\n-- isolated TASK-0028 fault\n${sql}\n`);
}

function normalizedDump(output: string): string {
  return output
    .split('\n')
    .filter((line) => !/^\\(?:un)?restrict\b/.test(line))
    .filter((line) => !/^-- Dumped (?:from database|by pg_dump)/.test(line))
    .join('\n');
}

async function dump(
  kind: '--schema-only' | '--data-only',
  env: NodeJS.ProcessEnv,
) {
  const result = await run(
    'pg_dump',
    [kind, '--no-comments', '-d', expectedDatabase],
    {
      cwd: repo,
      env,
    },
  );
  if (result.code !== 0)
    throw new Error(`pg_dump ${kind} failed (credentials withheld)`);
  return digest(normalizedDump(result.output));
}

async function snapshot(
  owner: pg.Client,
  env: NodeJS.ProcessEnv,
): Promise<Snapshot> {
  const globals = await owner.query(`
    SELECT jsonb_build_object(
      'priority_roles', COALESCE((
        SELECT jsonb_agg(to_jsonb(r) ORDER BY r.rolname)
        FROM (SELECT rolname, rolsuper, rolinherit, rolcreaterole, rolcreatedb,
                     rolcanlogin, rolreplication, rolbypassrls
              FROM pg_roles WHERE rolname IN ('role_rait_priority_writer', 'role_app_backend')) r
      ), '[]'::jsonb),
      'memberships', COALESCE((
        SELECT jsonb_agg(jsonb_build_object('role', role.rolname, 'member', member.rolname)
                         ORDER BY role.rolname, member.rolname)
        FROM pg_auth_members m
        JOIN pg_roles role ON role.oid = m.roleid
        JOIN pg_roles member ON member.oid = m.member
        WHERE role.rolname = 'role_rait_priority_writer'
           OR member.rolname = 'role_rait_priority_writer'
      ), '[]'::jsonb),
      'settings', COALESCE((
        SELECT jsonb_agg(jsonb_build_object('database', d.datname,
                                            'role', r.rolname,
                                            'config', s.setconfig)
                         ORDER BY d.datname, r.rolname)
        FROM pg_db_role_setting s
        JOIN pg_database d ON d.oid = s.setdatabase
        LEFT JOIN pg_roles r ON r.oid = s.setrole
        WHERE d.datname = current_database()
      ), '[]'::jsonb)
    ) AS value
  `);
  return {
    schema: await dump('--schema-only', env),
    data: await dump('--data-only', env),
    globals: digest(JSON.stringify(globals.rows[0].value)),
    roles: digest(
      JSON.stringify({
        priority_roles: globals.rows[0].value.priority_roles,
        memberships: globals.rows[0].value.memberships,
      }),
    ),
  };
}

function quoted(identifier: string): string {
  return `"${identifier.replaceAll('"', '""')}"`;
}

async function legacyRows(
  owner: pg.Client,
  baseline?: LegacyTable[],
): Promise<LegacyTable[]> {
  const tables =
    baseline ??
    (
      await owner.query(
        `SELECT n.nspname AS schema, c.relname AS table
       FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
       WHERE c.relkind IN ('r', 'p')
         AND n.nspname IN ('auth', 'tenancy', 'audit', 'storage',
                             'integration', 'inf', 'est', 'ch', 'ops')
       ORDER BY n.nspname, c.relname`,
      )
    ).rows;
  const result: LegacyTable[] = [];
  for (const entry of tables) {
    const schema = entry.schema as string;
    const table = entry.table as string;
    const columns = baseline
      ? (entry.columns as string[])
      : (
          await owner.query(
            `SELECT a.attname AS name FROM pg_attribute a
             WHERE a.attrelid = $1::regclass AND a.attnum > 0 AND NOT a.attisdropped
             ORDER BY a.attnum`,
            [`${quoted(schema)}.${quoted(table)}`],
          )
        ).rows.map((row) => row.name as string);
    const projection = columns.map(quoted).join(', ');
    const rows = await owner.query(
      `SELECT ${projection} FROM ${quoted(schema)}.${quoted(table)}`,
    );
    const sorted = rows.rows
      .map((row) => JSON.stringify(columns.map((column) => row[column])))
      .sort();
    result.push({
      schema,
      table,
      columns,
      hash: digest(JSON.stringify(sorted)),
    });
  }
  return result;
}

async function structuralCatalog(owner: pg.Client): Promise<string> {
  const result = await owner.query(`
    SELECT jsonb_build_object(
      'schemas', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'name', nspname, 'owner', pg_get_userbyid(nspowner), 'acl', nspacl::text)
        ORDER BY nspname), '[]'::jsonb)
        FROM pg_namespace WHERE nspname IN
          ('auth','tenancy','audit','storage','integration','inf','est','ch','ops')),
      'relations', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'schema', n.nspname, 'name', c.relname, 'kind', c.relkind,
        'owner', pg_get_userbyid(c.relowner), 'acl', c.relacl::text,
        'rls', c.relrowsecurity, 'force', c.relforcerowsecurity,
        'options', c.reloptions)
        ORDER BY n.nspname, c.relname), '[]'::jsonb)
        FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname IN ('auth','tenancy','audit','storage','integration','inf','est','ch','ops')),
      'columns', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'schema', n.nspname, 'table', c.relname, 'name', a.attname,
        'type', format_type(a.atttypid, a.atttypmod), 'not_null', a.attnotnull,
        'default', pg_get_expr(d.adbin, d.adrelid), 'identity', a.attidentity,
        'generated', a.attgenerated)
        ORDER BY n.nspname, c.relname, a.attnum), '[]'::jsonb)
        FROM pg_attribute a JOIN pg_class c ON c.oid = a.attrelid
        JOIN pg_namespace n ON n.oid = c.relnamespace
        LEFT JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum
        WHERE a.attnum > 0 AND NOT a.attisdropped
          AND n.nspname IN ('auth','tenancy','audit','storage','integration','inf','est','ch','ops')),
      'constraints', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'schema', n.nspname, 'table', c.relname, 'name', k.conname,
        'definition', pg_get_constraintdef(k.oid), 'deferred', k.condeferrable)
        ORDER BY n.nspname, c.relname, k.conname), '[]'::jsonb)
        FROM pg_constraint k JOIN pg_namespace n ON n.oid = k.connamespace
        LEFT JOIN pg_class c ON c.oid = k.conrelid
        WHERE n.nspname IN ('auth','tenancy','audit','storage','integration','inf','est','ch','ops')),
      'indexes', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'schema', n.nspname, 'name', c.relname,
        'definition', pg_get_indexdef(c.oid))
        ORDER BY n.nspname, c.relname), '[]'::jsonb)
        FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname IN ('auth','tenancy','audit','storage','integration','inf','est','ch','ops')),
      'policies', (SELECT COALESCE(jsonb_agg(to_jsonb(p)
        ORDER BY p.schemaname, p.tablename, p.policyname), '[]'::jsonb)
        FROM pg_policies p WHERE p.schemaname IN
          ('auth','tenancy','audit','storage','integration','inf','est','ch','ops')),
      'triggers', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'schema', n.nspname, 'table', c.relname, 'name', t.tgname,
        'definition', pg_get_triggerdef(t.oid), 'enabled', t.tgenabled)
        ORDER BY n.nspname, c.relname, t.tgname), '[]'::jsonb)
        FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname IN ('auth','tenancy','audit','storage','integration','inf','est','ch','ops')),
      'functions', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'schema', n.nspname, 'name', p.proname,
        'arguments', pg_get_function_identity_arguments(p.oid),
        'definition', pg_get_functiondef(p.oid),
        'owner', pg_get_userbyid(p.proowner), 'acl', p.proacl::text,
        'config', p.proconfig)
        ORDER BY n.nspname, p.proname, pg_get_function_identity_arguments(p.oid)), '[]'::jsonb)
        FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE n.nspname IN ('auth','tenancy','audit','storage','integration','inf','est','ch','ops'))
    ) AS value
  `);
  return digest(JSON.stringify(result.rows[0].value));
}

async function assertAppIdentity(app: pg.Client): Promise<void> {
  const result = await app.query(
    `SELECT current_database() AS db, current_user AS user, current_role AS role,
            r.rolsuper AS superuser, r.rolbypassrls AS bypass_rls, r.rolcanlogin AS login
     FROM pg_roles r WHERE r.rolname = current_role`,
  );
  expect(result.rows).toEqual([
    {
      db: expectedDatabase,
      user: 'role_app_backend',
      role: 'role_app_backend',
      superuser: false,
      bypass_rls: false,
      login: false,
    },
  ]);
}

describe('CTG-0001-C4-OD V3 pre-SQL static apply contract', () => {
